/**
 * The digital-fly archive (docs/benchmarks/fly-behavior/): what a record's
 * folder holds and how it is checked.
 *
 * Every file in a record's folder is derived from its record.json, and
 * registry-run.json is checked against it: the report and summary are
 * regenerated byte for byte, so editing any of them is caught. Records made
 * under digital-fly-behavior/v1, before the integrity rules, are legacy:
 * checked for what can still be checked, never counted as evidence.
 * Server only: it reads the disk and asks git.
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { basename, join } from "node:path";
import { evaluate } from "../experiments/evaluate.js";
import { redact } from "../experiments/provenance.js";
import { assembleDefinition } from "../experiments/registry.js";
import { canonicalJson, sha256Json } from "../sha256.js";
import {
  describeFlyBaseline,
  describeFlyTreatment,
  flyEngineText,
  flyIdentity,
  flyReceiptErrors,
  flyReplaySha256,
} from "./fly.js";
import { flyAuthorizedBy, flyRegistryDraft, flySubmission } from "./flyRegistry.js";
import {
  FLY_ALPHA,
  FLY_LEGACY_RECORD,
  FLY_METRICS,
  FLY_MIN_UNTIED_PAIRS,
  FLY_PROTOCOLS,
  FLY_RECORD,
  type FlyDesign,
  type FlyRecord,
} from "./contracts.js";

type Json = Record<string, unknown>;
/** The registry's run for an admitted record, or why it was not admitted. */
export interface FlyAdmission {
  registry_run: Json | null;
  error: string | null;
}

export const flyJsonText = (data: unknown) => JSON.stringify(data, null, 2) + "\n";
const fmt = (x: number | null | undefined, d = 3) =>
  typeof x === "number" ? x.toFixed(d) : "—";
const fmtP = (p: number | null | undefined) =>
  typeof p !== "number" ? "—" : p >= 0.001 ? p.toFixed(4) : p.toExponential(2);
const protocolOf = (record: FlyRecord) =>
  FLY_PROTOCOLS.find((p) => p.id === record.plan.experiment.protocol)!;

/** A record's label in the archive: who designed it and which protocol. */
export const flyLabel = (record: FlyRecord) =>
  `${record.plan.design.provenance.generation}: ${protocolOf(record).title.toLowerCase()}`;

function outcomeOf(record: FlyRecord, admission: FlyAdmission): string {
  if (admission.registry_run) return `${record.result.status} (${record.result.verdict})`;
  return record.development
    ? "development record (not admitted)"
    : "not admitted by the registry";
}

/** How a design came to be, in words that claim no more than was checked. */
function designOrigin(design: FlyDesign, record: FlyRecord): string {
  switch (design.provenance.generation) {
    case "model":
      return `Design proposed by a model: its receipt \`${design.provenance.decision_sha256}\` is receipt.json, and the design is exactly the one the receipt's answer states`;
    case "human":
      return `Design declared as written by a person; ${record.authorization.operator} attested that at the terminal (identity not verified)`;
    case "scripted":
      return "Design written by the host's demonstration script (flyExample.ts); no model or person wrote it";
  }
}

/** summary.json: what the archive's index lists, all of it from the record. */
export function flySummary(record: FlyRecord, admission: FlyAdmission): Json {
  const m = record.result.measurements;
  return {
    label: flyLabel(record),
    protocol: record.plan.experiment.protocol,
    outcome: outcomeOf(record, admission),
    evidence: admission.registry_run
      ? "admitted"
      : record.development
        ? "development"
        : "not admitted",
    generation: record.plan.design.provenance.generation,
    authorized_by: flyAuthorizedBy(record.authorization),
    question: record.plan.ir.question,
    metric: record.plan.design.analysis.metric,
    mean_paired_delta: m.mean_paired_delta ?? null,
    untied_pairs: m.untied_pairs ?? null,
    sign_test_p_expected: m.sign_test_p_expected ?? null,
    sign_test_p_opposite: m.sign_test_p_opposite ?? null,
    gate_refusals: m.gate_refusals ?? null,
    replay_sha256: admission.registry_run ? flyReplaySha256(record) : null,
    registry_experiment_id: record.preregistration.experiment_id,
    registry_run_id: admission.registry_run
      ? String(admission.registry_run.run_id ?? "")
      : null,
    fly: record.plan.fly,
    fly_sha256: record.plan.fly_sha256,
    fly_source_sha256: record.plan.fly_source_sha256,
    engine: flyEngineText(record.engine),
    commit: record.code.commit,
    dirty: record.code.dirty,
    development: record.development,
    ...(admission.error ? { admission_error: admission.error } : {}),
  };
}

/** report.md: a pure function of the record and its admission. */
export function flyReport(record: FlyRecord, admission: FlyAdmission): string {
  const m = record.result.measurements,
    plan = record.plan,
    design = plan.design,
    metric = design.analysis.metric,
    auth = record.authorization;
  const primary = FLY_METRICS.find((x) => x.id === metric)!;
  const protocol = protocolOf(record);
  const sign = design.analysis.expected_direction === "increase" ? 1 : -1;
  const runs = record.result.runs;
  const rows = record.seeds.map((s) => {
    const at = (arm: string) =>
      runs.find((r) => r.arm === arm && r.seed === s && r.block === primary.block);
    const c = at("control"),
      t = at("treatment");
    const cv = c?.metrics[metric] ?? null,
      tv = t?.metrics[metric] ?? null;
    const d = cv !== null && tv !== null ? tv - cv : null;
    const direction =
      d === null
        ? "undefined"
        : d * sign > 0
          ? "expected"
          : d * sign < 0
            ? "opposite"
            : "tie";
    return `| ${s} | ${fmt(cv)} | ${fmt(tv)} | ${d === null ? "—" : fmt(d)} | ${direction} | \`${t?.final_hashes[0]?.slice(0, 12) ?? ""}\` |`;
  });
  const ev = record.result.evaluation;
  const crit = ev
    ? [
        ...[...ev.guards, ...ev.success, ...ev.failure].map(
          (c) =>
            `- **${c.id}** ${c.metric} ${c.op} ${c.value}: observed ${fmt(c.observed, 4)} — ${c.holds === null ? "not evaluable" : c.holds ? "holds" : "does not hold"}`,
        ),
        "",
        ev.summary,
      ]
    : [`- not evaluated: ${record.result.error ?? "no result"}`];
  const blocks = plan.experiment.blocks.map((b) => b.id as string);
  const others = FLY_METRICS.filter((x) => blocks.includes(x.block))
    .map(
      (x) =>
        `| ${x.id} | ${fmt(m[`control_${x.id}`])} | ${fmt(m[`treatment_${x.id}`])} | ${x.unit} |`,
    )
    .join("\n");
  const t = design.parameters.treatment;
  const run = admission.registry_run;
  const banners = [
    `> Simulated observations of the digital fly (${plan.fly}), a reduced-order controller that simulates no neurons, in a closed arena. Not evidence about Drosophila.`,
    ...(auth.channel === "script"
      ? [
          `> Authorized by the demonstration script (${auth.operator}), not by a person: a demonstration of the pipeline, not a reviewed experiment.`,
        ]
      : []),
    ...(record.development
      ? [
          "> Development record: run from uncommitted or unknown code, so it was not admitted and is not evidence.",
        ]
      : []),
    ...(!run && !record.development && admission.error
      ? [`> Not admitted by the registry: ${admission.error}`]
      : []),
  ];
  return `# ${plan.experiment_id}: ${record.result.status.toUpperCase()} (${record.result.verdict.replaceAll("_", " ")})

${banners.join("\n>\n")}

**Protocol.** ${protocol.title}: ${describeFlyTreatment(t)}, against ${describeFlyBaseline(t)}.
${protocol.caveat ? `\n**Caveat.** ${protocol.caveat}\n` : ""}
**Question (host-written).** ${plan.ir.question}

**Hypothesis (host-written).** ${plan.ir.hypothesis}

**Design words (${design.provenance.generation}).** ${design.hypothesis} — competing: ${design.competing_hypothesis}

## Seeds

${record.seeds.length} seeds, drawn by the host after preregistration as SHA-256(receipt digest ‖ nonce ‖ counter): ${record.seeds.join(", ")}.

## Primary metric: ${metric} (${primary.unit})

| seed | control | treatment | difference | direction | treatment final state |
| ---: | ---: | ---: | ---: | :--- | :--- |
${rows.join("\n")}

${m.seeds_expected_direction ?? "—"} of ${m.untied_pairs ?? "—"} untied seeds in the expected direction (${design.analysis.expected_direction}), ${m.seeds_opposite ?? "—"} opposite, ${m.seeds_unchanged ?? "—"} tied, ${m.seeds_undefined ?? "—"} undefined. Exact one-sided sign test: p = ${fmtP(m.sign_test_p_expected)} for the expected direction, p = ${fmtP(m.sign_test_p_opposite)} for the opposite (alpha ${FLY_ALPHA}, at least ${FLY_MIN_UNTIED_PAIRS} untied seeds). Mean control ${fmt(m.control_mean)}, mean treatment ${fmt(m.treatment_mean)}, mean paired difference **${fmt(m.mean_paired_delta)}** (minimum effect ${design.analysis.minimum_effect} ${primary.unit}).

The fly's gate refused ${m.gate_refusals ?? "—"} commands (control ${m.control_gate_refusals ?? "—"}, treatment ${m.treatment_gate_refusals ?? "—"}).

## Frozen criteria (rain-criteria/v1, evaluated by the registry)

${crit.join("\n")}

${run ? `Registry run \`${String(run.run_id ?? "")}\`: status **${String(run.status)}**, verdict **${String(run.hypothesis_verdict)}**.` : "Not admitted by the registry: no registry run."}

## Every measurement (mean over seeds where defined; not preregistered as tests)

| metric | control | treatment | unit |
| :--- | ---: | ---: | :--- |
${others}

## Provenance

- Plan \`${plan.definition_sha256}\`; fly \`${plan.fly}\`, identity \`${plan.fly_sha256}\`, source \`${plan.fly_source_sha256}\`
- Preregistered as ${record.preregistration.experiment_id} at ${record.preregistration.created_at} (receipt \`${auth.preregistration_sha256}\`)
- Authorized at ${auth.authorized_at} by ${flyAuthorizedBy(auth)}; nonce \`${auth.nonce}\`
- Record \`${record.sha256}\`, run \`${record.run_id}\`, ${record.started_at} to ${record.finished_at}
- Simulated on ${flyEngineText(record.engine)}: ${m.simulated_seconds ?? "—"} fly-seconds, then again for the determinism guard
- Code: ${record.code.commit ? `commit \`${record.code.commit}\`` : "commit unknown"}${record.code.dirty === false ? "" : record.code.dirty ? " with uncommitted changes" : ", tree state unknown"}
- ${designOrigin(design, record)}

## Limitations

${plan.ir.limitations.map((l) => `- ${l}`).join("\n")}
`;
}

/** Every file of a record's folder, as text, except a model design's receipt.json. */
export function flyFolderFiles(
  record: FlyRecord,
  admission: FlyAdmission,
): Record<string, string> {
  return {
    "design.json": flyJsonText(record.plan.design),
    "plan.json": flyJsonText(record.plan),
    "preregistration.json": flyJsonText(record.preregistration),
    "record.json": flyJsonText(record),
    ...(admission.registry_run
      ? { "registry-run.json": flyJsonText(admission.registry_run) }
      : {}),
    "summary.json": flyJsonText(flySummary(record, admission)),
    "report.md": flyReport(record, admission),
  };
}

/** What the registry's run must show for this record. */
export function flyRegistryRunErrors(run: Json, record: FlyRecord): string[] {
  const same = (a: unknown, b: unknown) => canonicalJson(a) === canonicalJson(b);
  const receipt = record.preregistration;
  const definition = (run.definition ?? {}) as Json;
  const provenance = (run.provenance ?? {}) as Json;
  // What admission submitted, as the registry stores it (it masks strings
  // under credential-like keys, so the same masking is applied here).
  const submission = flySubmission(record, flyReplaySha256(record));
  const expected = record.result.error
    ? null
    : evaluate(record.plan.criteria, record.result.measurements).evaluation;
  const checks: [boolean, string][] = [
    [run.experiment_id === receipt.experiment_id, "experiment id"],
    [
      run.status === record.result.status &&
        run.hypothesis_verdict === record.result.verdict,
      "status or verdict",
    ],
    [same(run.measurements, submission.measurements), "measurements"],
    [same(run.series, submission.series), "series"],
    [same(run.evaluation, expected), "evaluation"],
    [
      run.started_at === record.started_at && run.finished_at === record.finished_at,
      "times",
    ],
    [
      run.definition_sha256 === receipt.registry_definition_sha256 &&
        sha256Json(definition) === receipt.registry_definition_sha256 &&
        definition.created_at === receipt.created_at &&
        definition.experiment_id === receipt.experiment_id,
      "preregistered definition",
    ],
    [
      same(run.inputs, redact(submission.inputs)) &&
        same(run.observations, redact(submission.observations)),
      "inputs or observations",
    ],
    [same(provenance.producer, redact(submission.provenance)), "producer provenance"],
  ];
  // The registered definition must be this plan's own draft. Only this fly's
  // code can rebuild that; a record of other code still has its digest checked.
  if (record.plan.fly_sha256 === flyIdentity().fly_sha256)
    checks.push([
      same(
        definition,
        assembleDefinition(
          flyRegistryDraft(record.plan),
          receipt.experiment_id,
          receipt.created_at,
        ),
      ),
      "preregistered definition (not this plan's draft)",
    ]);
  return checks
    .filter(([ok]) => !ok)
    .map(([, what]) => `registry-run.json: ${what} differs from the record`);
}

const readJson = (path: string): unknown => JSON.parse(readFileSync(path, "utf8"));

export type FlyFolderKind = "record" | "legacy" | "refused";
export interface FlyFolderCheck {
  kind: FlyFolderKind;
  /** Problems with the folder's files; any one fails the folder. */
  errors: string[];
  record: FlyRecord | null;
  admission: FlyAdmission | null;
}

/**
 * Checks every file of a record's folder against its record.json (without
 * re-simulating): exact files, nothing extra, the registry run, the model
 * receipt. A legacy (v1) folder gets the checks that still apply.
 */
export function checkFlyFolder(dir: string): FlyFolderCheck {
  const names = readdirSync(dir).sort();
  if (!names.includes("record.json")) {
    const refused = names.includes("summary.json")
      ? (readJson(join(dir, "summary.json")) as Json)
      : null;
    const allowed = new Set(["design.json", "receipt.json", "summary.json"]);
    return {
      kind: "refused",
      errors: [
        ...(refused?.outcome === "refused by the host compiler" &&
        Array.isArray(refused.errors) &&
        refused.errors.length &&
        names.includes("design.json")
          ? []
          : [
              "no record.json, and not a refusal (design.json and a summary listing why)",
            ]),
        ...names.filter((n) => !allowed.has(n)).map((n) => `unexpected file ${n}`),
      ],
      record: null,
      admission: null,
    };
  }
  let raw: Json;
  try {
    raw = readJson(join(dir, "record.json")) as Json;
  } catch {
    return {
      kind: "record",
      errors: ["record.json is not JSON"],
      record: null,
      admission: null,
    };
  }
  if (raw.schema === FLY_LEGACY_RECORD) return legacyFolder(dir, names, raw);
  if (raw.schema !== FLY_RECORD)
    return {
      kind: "record",
      errors: [`record.json has unknown schema ${String(raw.schema)}`],
      record: null,
      admission: null,
    };
  const record = raw as unknown as FlyRecord;
  const errors: string[] = [];
  // One folder per plan, named by it: a copy under another name is not a second run.
  if (basename(dir) !== record.plan?.experiment_id)
    errors.push("the folder is not named by its plan's experiment id");
  let summary: Json = {};
  let run: Json | null = null;
  try {
    summary = readJson(join(dir, "summary.json")) as Json;
    if (names.includes("registry-run.json"))
      run = readJson(join(dir, "registry-run.json")) as Json;
  } catch {
    errors.push("summary.json or registry-run.json is not JSON");
  }
  const admission: FlyAdmission = {
    registry_run: run,
    error: typeof summary.admission_error === "string" ? summary.admission_error : null,
  };
  try {
    const expected = flyFolderFiles(record, admission);
    const model = record.plan.design.provenance.generation === "model";
    for (const [name, text] of Object.entries(expected))
      if (!names.includes(name)) errors.push(`missing ${name}`);
      else if (readFileSync(join(dir, name), "utf8") !== text)
        errors.push(`${name} is not what record.json implies`);
    for (const name of names)
      if (!(name in expected) && !(model && name === "receipt.json"))
        errors.push(`unexpected file ${name}`);
    if (run) errors.push(...flyRegistryRunErrors(run, record));
    if (model)
      errors.push(
        ...(names.includes("receipt.json")
          ? flyReceiptErrors(
              record.plan.design,
              readFileSync(join(dir, "receipt.json"), "utf8"),
            )
          : ["a model's design needs receipt.json"]),
      );
  } catch (e) {
    errors.push(`malformed record folder: ${e instanceof Error ? e.message : String(e)}`);
  }
  return { kind: "record", errors, record, admission };
}

/** The six digital-fly/2 records made before the integrity rules: what still holds. */
function legacyFolder(dir: string, names: string[], record: Json): FlyFolderCheck {
  const errors: string[] = [];
  if (basename(dir) !== (record.plan as Json | undefined)?.experiment_id)
    errors.push("the folder is not named by its plan's experiment id");
  const same = (a: unknown, b: unknown) => canonicalJson(a) === canonicalJson(b);
  try {
    const { sha256: sealed, ...body } = record;
    if (sha256Json(body) !== sealed) errors.push("record digest mismatch");
    const plan = record.plan as Json & { design: unknown; definition_sha256: string };
    const result = record.result as Json & {
      status: string;
      verdict: string;
      measurements: Json;
    };
    const file = (name: string) =>
      names.includes(name) ? (readJson(join(dir, name)) as Json) : null;
    if (!same(file("design.json"), plan.design))
      errors.push("design.json is not the record's");
    if (!same(file("plan.json"), plan)) errors.push("plan.json is not the record's");
    const prereg = file("preregistration.json");
    if (prereg?.plan_sha256 !== plan.definition_sha256)
      errors.push("preregistration.json binds another plan");
    const run = file("registry-run.json");
    if (run) {
      const inputs = (run.inputs ?? {}) as Json;
      if (
        run.experiment_id !== prereg?.experiment_id ||
        run.status !== result.status ||
        run.hypothesis_verdict !== result.verdict ||
        !same(run.measurements, result.measurements) ||
        !same(inputs.scientific_plan, plan)
      )
        errors.push("registry-run.json is not the record's");
    }
    const summary = file("summary.json");
    if (
      !summary ||
      !(
        summary.outcome === `${result.status} (${result.verdict})` ||
        (summary.outcome === "not admitted by the registry" && !run)
      ) ||
      summary.metric !==
        (plan.design as { analysis?: { metric?: unknown } }).analysis?.metric ||
      summary.question !== (plan.ir as { question?: unknown } | undefined)?.question ||
      summary.mean_paired_delta !== result.measurements.mean_paired_delta
    )
      errors.push("summary.json is not the record's");
    const report = names.includes("report.md")
      ? readFileSync(join(dir, "report.md"), "utf8")
      : "";
    if (
      !report.startsWith(
        `# ${String(plan.experiment_id)}: ${result.status.toUpperCase()}`,
      )
    )
      errors.push("report.md does not report the record's outcome");
    const allowed = new Set([
      "design.json",
      "plan.json",
      "preregistration.json",
      "record.json",
      "registry-run.json",
      "report.md",
      "summary.json",
      "receipt.json",
    ]);
    errors.push(
      ...names.filter((n) => !allowed.has(n)).map((n) => `unexpected file ${n}`),
    );
  } catch (e) {
    errors.push(`malformed legacy folder: ${e instanceof Error ? e.message : String(e)}`);
  }
  return { kind: "legacy", errors, record: null, admission: null };
}

/** Every run the archive holds: the plan, the fly and the seeds, read from record.json. */
export function archivedFlyRuns(
  archive: string,
): { dir: string; plan_sha256: string; fly_sha256: string; seeds: number[] }[] {
  if (!existsSync(archive)) return [];
  const runs: {
    dir: string;
    plan_sha256: string;
    fly_sha256: string;
    seeds: number[];
  }[] = [];
  for (const d of readdirSync(archive, { withFileTypes: true })) {
    const path = join(archive, d.name, "record.json");
    if (!d.isDirectory() || !existsSync(path)) continue;
    try {
      const r = readJson(path) as {
        plan?: {
          definition_sha256?: unknown;
          fly_sha256?: unknown;
          experiment?: { seeds?: unknown };
        };
        seeds?: unknown;
      };
      const seeds = Array.isArray(r.seeds) ? r.seeds : r.plan?.experiment?.seeds;
      if (
        typeof r.plan?.definition_sha256 === "string" &&
        typeof r.plan.fly_sha256 === "string" &&
        Array.isArray(seeds)
      )
        runs.push({
          dir: d.name,
          plan_sha256: r.plan.definition_sha256,
          fly_sha256: r.plan.fly_sha256,
          seeds: seeds.filter((s): s is number => typeof s === "number"),
        });
    } catch {
      // Not a record: --verify reports it.
    }
  }
  return runs;
}

/** README.md for the archive: every folder, what it is and what it may be used for. */
export function flyArchiveReadme(archive: string): string {
  const rows = readdirSync(archive, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(archive, d.name, "summary.json")))
    .map((d) => {
      const s = readJson(join(archive, d.name, "summary.json")) as Json;
      let legacy = false;
      try {
        legacy =
          (readJson(join(archive, d.name, "record.json")) as Json).schema ===
          FLY_LEGACY_RECORD;
      } catch {
        // A refusal has no record.
      }
      const refused = s.outcome === "refused by the host compiler";
      const evidence = refused
        ? "refused before preregistration"
        : legacy
          ? "legacy: exploratory only"
          : s.evidence === "admitted"
            ? String(s.authorized_by ?? "").startsWith("the demonstration script")
              ? "admitted; script-authorized demonstration"
              : "admitted"
            : String(s.evidence ?? "not admitted");
      const file = existsSync(join(archive, d.name, "report.md"))
        ? "report.md"
        : "summary.json";
      return `| [${d.name}](${d.name}/${file}) | ${String(s.protocol ?? "—")} | ${String(s.outcome)} | ${evidence} | ${String(s.generation ?? "—")} | ${String(s.question ?? "—").replaceAll("|", "/")} |`;
    })
    .sort();
  return `# Digital fly behaviour experiments

Every digital-fly experiment the R.A.I.N. Lab compiled, ran or refused, written by
\`npm run rain:fly\`. Nothing here is edited by hand: refusals, failures,
inconclusive results and runs the registry would not admit stay beside the
successes, and every file in a record's folder is derived from its record.json.

All results are **simulated observations of the digital fly**, a reduced-order
behavioural controller on FlyBody's anatomy that simulates no neurons, in a
closed arena. They describe that simulator only and are not evidence about
Drosophila.

- **Records under digital-fly-behavior/v2** (rain-fly-record/v2) were
  preregistered before they ran, on seeds the host drew afterwards from the
  registry receipt and a random nonce, and decided by an exact one-sided sign
  test at alpha ${FLY_ALPHA} with at least ${FLY_MIN_UNTIED_PAIRS} untied seeds. \`npm run rain:fly:verify\`
  re-simulates each on the JavaScript engine that made it and checks every file
  of its folder.
- **Script-authorized records** were authorized by the demonstration script
  (Scripted.DemoOperator), not by a person: they demonstrate the pipeline on the
  host's own designs. Their reports say so.
- **Legacy records** (rain-fly-record/v1) were made under digital-fly/2 before
  these integrity rules: from an uncommitted tree, on seeds the designer chose,
  authorized by a script. They are kept because the archive keeps everything
  that ran, and they are **exploratory only, not evidence**. Verification checks
  their seal, summary and files, and neither fails nor passes them as evidence.
- Some protocols cannot discriminate as designed (obstacle avoidance and noisy
  sensing), visual threat only checks the implementation's expansion gate, and
  adaptation's interval depends on the fly's response; each report's caveat
  says so. They are to be redesigned, with pilots that size the thresholds.

| folder | protocol | outcome | standing | design by | question |
| :--- | :--- | :--- | :--- | :--- | :--- |
${rows.join("\n")}
`;
}
